python3 -c "
import os, signal
ports = [3000, 8000]
target_ports_hex = {f'{port:04X}' for port in ports}
target_inodes = set()
for proto in ('tcp', 'tcp6', 'udp', 'udp6'):
    path = f'/proc/net/{proto}'
    if not os.path.exists(path):
        continue
    try:
        with open(path, 'r') as f:
            lines = f.readlines()
        for line in lines[1:]:
            parts = line.strip().split()
            if len(parts) < 10:
                continue
            local_addr = parts[1]
            inode = parts[9]
            if ':' in local_addr:
                port_hex = local_addr.split(':')[-1]
                if port_hex in target_ports_hex:
                    target_inodes.add(inode)
    except Exception:
        pass
if target_inodes:
    pids_to_kill = set()
    for pid_str in os.listdir('/proc'):
        if not pid_str.isdigit():
            continue
        pid = int(pid_str)
        if pid == os.getpid():
            continue
        fd_dir = f'/proc/{pid_str}/fd'
        if not os.path.exists(fd_dir):
            continue
        try:
            for fd in os.listdir(fd_dir):
                fd_path = os.path.join(fd_dir, fd)
                if os.path.islink(fd_path):
                    target = os.readlink(fd_path)
                    if target.startswith('socket:['):
                        inode = target[8:-1]
                        if inode in target_inodes:
                            pids_to_kill.add(pid)
        except Exception:
            pass
    for pid in pids_to_kill:
        try:
            print(f'Killing process {pid} using port(s)')
            os.kill(pid, signal.SIGKILL)
        except Exception as e:
            print(f'Failed to kill {pid}: {e}')
"
sleep 1
ps -p $SERVER_PID || echo "Process successfully killed!"
